-- Seed Mathematics Units (16 units) with proper UUIDs
INSERT INTO public.units (id, subject_id, unit_number, title, description, icon_emoji, total_xp, duration_weeks) VALUES
('11111111-0001-0001-0001-000000000001', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 1, 'Number & Operations', 'Master natural numbers, integers, fractions, decimals, and basic arithmetic operations.', '🔢', 450, '2-3 weeks'),
('11111111-0001-0001-0001-000000000002', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 2, 'Fractions, Decimals & Percentages', 'Work with fractions, decimals, percentages and their conversions.', '🧮', 500, '2-3 weeks'),
('11111111-0001-0001-0001-000000000003', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 3, 'Ratios, Rates & Proportions', 'Understand ratios, direct and inverse proportions, and rate problems.', '⚖️', 400, '2 weeks'),
('11111111-0001-0001-0001-000000000004', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 4, 'Algebra Fundamentals', 'Learn algebraic expressions, simplification, and basic equations.', '🔤', 550, '3 weeks'),
('11111111-0001-0001-0001-000000000005', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 5, 'Linear Equations & Inequalities', 'Solve linear equations, inequalities, and simultaneous equations.', '📊', 600, '3 weeks'),
('11111111-0001-0001-0001-000000000006', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 6, 'Quadratic Equations', 'Master factorization, quadratic formula, and graphing parabolas.', '📈', 500, '2-3 weeks'),
('11111111-0001-0001-0001-000000000007', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 7, 'Functions & Graphs', 'Explore function notation, transformations, and graphical analysis.', '📉', 550, '3 weeks'),
('11111111-0001-0001-0001-000000000008', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 8, 'Sequences & Series', 'Work with arithmetic and geometric sequences and series.', '🔁', 400, '2 weeks'),
('11111111-0001-0001-0001-000000000009', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 9, 'Geometry Fundamentals', 'Study angles, triangles, polygons, and geometric properties.', '📐', 600, '3 weeks'),
('11111111-0001-0001-0001-000000000010', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 10, 'Mensuration', 'Calculate perimeters, areas, surface areas, and volumes.', '📏', 550, '3 weeks'),
('11111111-0001-0001-0001-000000000011', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 11, 'Trigonometry', 'Master trigonometric ratios, graphs, and applications.', '📐', 600, '3 weeks'),
('11111111-0001-0001-0001-000000000012', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 12, 'Coordinate Geometry', 'Work with coordinates, straight lines, and circles.', '🗺️', 500, '2-3 weeks'),
('11111111-0001-0001-0001-000000000013', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 13, 'Vectors & Transformations', 'Understand vectors, matrices, and geometric transformations.', '➡️', 450, '2-3 weeks'),
('11111111-0001-0001-0001-000000000014', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 14, 'Statistics', 'Analyze data with mean, median, mode, and statistical diagrams.', '📊', 500, '2-3 weeks'),
('11111111-0001-0001-0001-000000000015', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 15, 'Probability', 'Calculate probabilities, tree diagrams, and combined events.', '🎲', 400, '2 weeks'),
('11111111-0001-0001-0001-000000000016', '22c9be77-9ec7-44d3-9c20-04cad5f895e6', 16, 'Sets & Venn Diagrams', 'Work with set notation, operations, and Venn diagrams.', '⭕', 350, '2 weeks')
